<style lang="scss" scoped src="./table-cell.scss"></style>

<script>
import { DateTime } from 'luxon';
import { Component, Prop, Vue } from 'vue-property-decorator';
import { has } from '../../util/has';
import { AvatarSize } from '../../components/avatar/avatar.constants.js';
import Avatar from '../../components/avatar/avatar';
import {
  TableCellAlignment,
  TableCellAlignmentValues,
  TableCellMode,
  TableCellModeValues,
  TableCellSize,
  TableCellSizeValues,
  TableCellStatus,
  TableDataType,
  TableDataTypeValues
} from '../table/table.constants';
import { TableRowMode, TableRowModeValue } from './table-cell.constants';

const statusToString = {
  [TableCellStatus.ACTIVE]: 'Active',
  [TableCellStatus.COMPLETE]: 'Complete',
  [TableCellStatus.EXPIRED]: 'Expired',
  [TableCellStatus.FAILED]: 'Transaction Failed'
};

const statusToClass = {
  [TableCellStatus.ACTIVE]: 'TableCell--active',
  [TableCellStatus.COMPLETE]: 'TableCell--complete',
  [TableCellStatus.EXPIRED]: 'TableCell--expired',
  [TableCellStatus.FAILED]: 'TableCell-failed'
};

@Component({
  components: {
    Avatar
  }
})
export default class TableCell extends Vue {
  @Prop({
    type: String,
    default: TableCellAlignment.LEFT,
    validator: has(TableCellAlignmentValues)
  })
  align;

  @Prop({
    type: String,
    default: TableCellSize.SMALL,
    validator: has(TableCellSizeValues)
  })
  size;

  @Prop({
    type: String,
    default: TableCellMode.PRIMARY,
    validator: has(TableCellModeValues)
  })
  mode;

  @Prop({
    type: String,
    default: TableRowMode.DEFAULT,
    validator: has(TableRowModeValue)
  })
  rowMode;

  @Prop({
    type: Boolean,
    default: false
  })
  warning;

  @Prop({
    type: Boolean,
    default: false
  })
  expired;

  @Prop({
    type: String,
    default: TableDataType,
    validator: has(TableDataTypeValues)
  })
  type;

  @Prop({
    type: Function,
    default: () => {}
  })
  format;

  @Prop({
    type: [String, Number, Date, Boolean, Object],
    default: ''
  })
  data;

  @Prop({
    type: Array,
    default: () => []
  })
  options;

  @Prop({
    type: String,
    default: ''
  })
  imageSrc;

  @Prop({
    type: Boolean,
    default: true
  })
  hasBorder;

  AvatarSize = AvatarSize;
  TableDataType = TableDataType;

  get borderClass() {
    return this.hasBorder ? 'TableCell--has_border' : 'TableCell--no_border';
  }

  get alignClass() {
    return this.align;
  }

  get sizeClass() {
    return this.size;
  }

  get modeClass() {
    if (this.warning) {
      return 'TableCell--warning';
    }

    if (this.expired) {
      return 'TableCell--expired';
    }

    return this.mode;
  }

  get rowModeClass() {
    return this.rowMode;
  }

  get statusClass() {
    if (!this.warning) {
      return statusToClass[this.data];
    }

    return '';
  }

  get statusString() {
    return statusToString[this.data];
  }

  get content() {
    switch (this.type) {
      case TableDataType.MONEY:
        return this.data || '$0.00';
      case TableDataType.NAME:
        return `${this.data.firstName} ${this.data.lastName}`;
      case TableDataType.DATE:
        return this.data
          ? DateTime.fromISO(this.data)
              .setZone('UTC')
              .toFormat('MM/dd/yy HH:mm')
          : '';
      case TableDataType.CUSTOM:
        return this.format(this.data);
      default:
        return `${this.data || ''}`;
    }
  }

  handleSendMessage() {
    this.$emit('onSendMessage');
  }

  handleThankDonor() {
    this.$emit('onThankDonor');
  }

  handleBatchId(e) {
    e.preventDefault();

    const eventHub = window['eventHub'];
    const batchIdLink = `/reconciliation/funding-batches/${this.data}`;

    if (eventHub) {
      // ask GMS2 to route us to the correct record -- leave query params out of it because GMS2 can't handle them
      eventHub.emit('navigation', batchIdLink);
    } else {
      window.open(batchIdLink, '_blank');
    }
  }
}
</script>

<template>
  <div
    :class="[
      'TableCell',
      alignClass,
      sizeClass,
      modeClass,
      rowModeClass,
      borderClass
    ]"
  >
    <div v-if="type === TableDataType.THANK" class="TableCell__ThankCell">
      <div v-if="data.anonymous" class="TableCell_NoThanks"></div>
      <div v-else-if="data.thanked === true" class="TableCell__Thanked">
        <div class="TableCell__ThankedMessage">{{ 'Thanked!' }}</div>
        <div class="TableCell__SendMessage" @click="handleSendMessage">
          <span class="TableCell__DoubleSlash">//</span>
          {{ 'Send another message' }}
        </div>
      </div>
      <div v-else class="TableCell__ThankDonor" @click="handleThankDonor">
        {{ `Thank ${data.donor} →` }}
      </div>
    </div>
    <div
      v-else-if="type === TableDataType.STATUS"
      :class="[statusClass, 'TableCell__Status']"
    >
      {{ statusString }}
    </div>
    <div v-else-if="type === TableDataType.AVATAR" class="TableCell--avatar">
      <div class="TableCell__Image">
        <Avatar :image="imageSrc" :isRound="false" :size="AvatarSize.TINY" />
      </div>
      <div class="TableCell__Content">{{ data.label }}</div>
    </div>
    <div v-else-if="type === TableDataType.LINK" class="TableCell--link">
      <a
        target="_blank"
        :href="`/donations/detail/${data}`"
        onclick="event.stopPropagation()"
        v-if="options && options[0] === 'transaction_id'"
      >
        {{ data }}
      </a>
      <a
        target="_blank"
        :href="`/reconciliation/funding-batches/${data}`"
        @click.stop="handleBatchId"
        v-else-if="options && options[0] === 'batch_id'"
      >
        {{ data }}
      </a>
      <span v-else>
        {{ data || '' }}
      </span>
    </div>
    <div v-else>
      {{ content }}
    </div>
  </div>
</template>
